        return True
    if n < k:
        return False
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    nums.sort(reverse=True)
    if nums and nums[0] > target:
        return False
    @lru_cache(maxsize=None)
    def dfs(remaining_groups, start_idx, cur_sum, used_mask):
        if remaining_groups == 1:
            return True
        if cur_sum == target:
            return dfs(remaining_groups - 1, 0, 0, used_mask)
        i = start_idx
        while i < n:
            if not (used_mask >> i) & 1 and cur_sum + nums[i] <= target:
                new_mask = used_mask | (1 << i)
                if dfs(remaining_groups, i + 1, cur_sum + nums[i], new_mask):
                    return True
                while i + 1 < n and nums[i] == nums[i + 1]:
                    i += 1
            i += 1
        return False
    return dfs(k, 0, 0, 0)

def solve(nums):
    n = len(nums)
    if n < 3:
        return 0
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + nums[i]
    total = pref[n]
    count = 0
    for i in range(1, n - 1):
        left = pref[i]
        for j in range(i + 1, n):
            middle = pref[j] - pref[i]
            right = total - pref[j]
            if left <= middle <= right:
                count += 1
    return count
